<template>
  <div class="work-page">
    <h1 data-scroll-reveal>Roles I've Had</h1>
    <article data-scroll-group data-scroll-step="110">
      <p>I have worked in university research labs, AI consulting, and digital transformation.</p>
      <ChapterRail :items="chapterItems" label="Work sections" />
      <div id="timeline" data-scroll-group data-scroll-step="140">
        <div data-scroll-group data-scroll-step="160">
          <section v-for="role in roles" :key="role.id" :id="`work-${role.year}`" class="year" data-scroll-group data-scroll-step="170">
            <h3>{{ role.year }}</h3>
            <section :id="role.anchor">
              <h4>{{ role.period }}</h4>
              <ul>
                <li class="image-wrapper work-logo"><img :src="role.media" :alt="role.organisation" :style="{ height: role.logoHeight }" /></li>
                <li class="title">{{ role.title }}</li>
                <li class="role">{{ role.organisation }}</li>
                <li class="location">{{ role.location }}</li>
                <li class="work-summary">{{ role.summary }}</li>
                <li class="work-detail-area">
                  <button type="button" class="work-disclosure" :aria-expanded="!!openRoles[role.id]" :aria-controls="`${role.anchor}-details`" @click="toggleRole(role.id, $event)">
                    <span>{{ openRoles[role.id] ? 'Less detail' : 'Work details' }}</span>
                    <svg viewBox="0 0 16 16" aria-hidden="true"><path d="M3 8h10" /><path class="work-plus" d="M8 3v10" /></svg>
                  </button>
                  <div :id="`${role.anchor}-details`" class="work-detail-panel" :class="{ 'is-open': openRoles[role.id], 'is-instant': instantRole === role.id }" :inert="!openRoles[role.id]" :aria-hidden="!openRoles[role.id]">
                    <div class="work-detail-content">
                      <div v-for="detail in role.details" :key="detail.title" class="work-detail">
                        <h5>
                          <router-link v-if="detail.route" :to="detail.route">{{ detail.title }}<ArrowUpRightIcon /></router-link>
                          <span v-else>{{ detail.title }}</span>
                        </h5>
                        <p>{{ detail.body }}</p>
                      </div>
                    </div>
                  </div>
                </li>
                <li class="work-view-links"><SourceViewLinks :source-id="`experience:${role.id}`" /></li>
              </ul>
            </section>
          </section>
        </div>
      </div>
    </article>
  </div>
</template>
<script>
import scrollRevealMixin from '../mixins/scrollRevealMixin';
import ChapterRail from './ChapterRail.vue';
import SourceViewLinks from './ui/SourceViewLinks.vue';
import { experienceEntries } from '../data/experienceEntries';
import { settleScrollToId } from '../utils/anchorLanding';
export default {
  name: 'ExperienceTab',
  components: { ChapterRail, SourceViewLinks },
  mixins: [scrollRevealMixin],
  data() {
    return {
      roles: experienceEntries, openRoles: {}, instantRole: '',
      chapterItems: [{ id: 'work-pwc', label: 'PwC' }, { id: 'work-slr', label: 'SLR' }, { id: 'work-hsbc', label: 'HSBC' }, { id: 'work-kiwiview', label: 'Kiwiview' }],
    };
  },
  mounted() { this.scrollToRouteHash(); },
  watch: { '$route.hash'() { this.scrollToRouteHash(); } },
  methods: {
    toggleRole(id, event) {
      this.instantRole = event.detail === 0 ? id : '';
      this.openRoles[id] = !this.openRoles[id];
    },
    scrollToRouteHash(attempt = 0) {
      const hash = this.$route.hash;
      if (!hash) return;
      let id = hash.replace(/^#/, '');
      try { id = decodeURIComponent(id); } catch { /* Keep a plain anchor. */ }
      const role = this.roles.find((entry) => entry.anchor === id);
      if (role) { this.instantRole = role.id; this.openRoles[role.id] = true; }
      this.$nextTick(() => {
        if (settleScrollToId(id)) return;
        if (attempt < 20) window.setTimeout(() => this.scrollToRouteHash(attempt + 1), 80);
      });
    },
  },
};
</script>
