<template>
  <main class="room-experience" :class="`is-${phase}`">
    <router-link class="room-exit" to="/home" aria-label="Return home">H.W.</router-link>

    <section v-if="phase === 'idle' || phase === 'error'" class="room-entry">
      <p class="room-kicker">A temporary listening room</p>
      <h1>Leave something here.</h1>
      <p class="room-intro">A sentence, a question, an unfinished thought. A room of unfamiliar voices will gather, listen, and respond, then disappear.</p>
      <form class="fragment-form" @submit.prevent="begin">
        <label class="sr-only" for="room-fragment">Your fragment</label>
        <textarea
          id="room-fragment"
          ref="fragmentInput"
          v-model="fragment"
          maxlength="500"
          rows="3"
          placeholder="There was a blue chair in my grandmother’s kitchen."
          @keydown.meta.enter.prevent="begin"
          @keydown.ctrl.enter.prevent="begin"
        ></textarea>
        <div class="fragment-actions">
          <span>{{ fragment.length }} / 500</span>
          <button type="submit" :disabled="!fragment.trim()">Let it enter</button>
        </div>
      </form>
      <p v-if="phase === 'error'" class="room-error" role="alert">{{ errorMessage }}</p>
      <p class="room-note">Headphones make the space easier to hear.</p>
    </section>

    <section v-else class="room-stage" aria-live="polite">
      <div class="room-field" aria-hidden="true">
        <span class="room-boundary"></span>
        <span class="room-breath" :style="breathStyle"></span>
        <span
          v-for="speaker in roomSpeakers"
          :key="speaker.id"
          class="room-presence"
          :class="{ 'is-speaking': activeSpeakers.has(speaker.id) }"
          :style="speaker.style"
        ></span>
      </div>

      <div class="room-state">
        <blockquote>“{{ scene?.fragment || submittedFragment }}”</blockquote>

        <template v-if="phase === 'composing' || phase === 'rendering'">
          <div class="listening-mark" aria-hidden="true"><i></i><i></i><i></i></div>
          <p class="room-status">{{ statusText }}</p>
        </template>

        <template v-else-if="phase === 'ready'">
          <p class="room-status">The room is waiting.</p>
          <button class="room-listen" type="button" @click="listen">Enter the room</button>
          <p class="room-note">Give it a little space after the final voice.</p>
        </template>

        <template v-else-if="phase === 'playing'">
          <p class="room-status">{{ playbackStatus }}</p>
          <div class="room-progress" aria-hidden="true"><span :style="{ transform: `scaleX(${progress})` }"></span></div>
          <button class="room-leave" type="button" @click="endEarly">Leave the room</button>
        </template>

        <template v-else-if="phase === 'ended'">
          <p class="room-status">The room has gone.</p>
          <button class="room-listen" type="button" @click="reset">Leave another fragment</button>
        </template>
      </div>
    </section>

    <details v-if="debug && scene" class="room-debug">
      <summary>Scene diagnostics</summary>
      <pre>{{ debugText }}</pre>
    </details>

    <p class="room-disclosure">The words and performances are generated for this moment. They do not express the voice owners’ views or experiences.</p>
  </main>
</template>

<script>
import { composeRoom, synthesiseRoomLine } from '../utils/roomSite';
import { RoomAudioEngine } from '../utils/roomAudio';
import { activeRoomSpeakers, resolveRoomTimeline, ROOM_SPACES } from '../utils/roomTimeline.mjs';

export default {
  name: 'RoomExperience',
  data() {
    return {
      fragment: '',
      submittedFragment: '',
      phase: 'idle',
      errorCode: '',
      scene: null,
      timeline: null,
      engine: null,
      audioContext: null,
      controller: null,
      renderedLines: 0,
      totalLines: 0,
      elapsed: 0,
      activeSpeakers: new Set(),
      animationFrame: 0,
    };
  },
  computed: {
    debug() {
      return this.$route.query.debug === '1';
    },
    roomSpeakers() {
      return (this.scene?.speakers || []).map((speaker, index) => {
        const space = ROOM_SPACES[speaker.space] || ROOM_SPACES.center;
        return {
          ...speaker,
          style: {
            left: `${space.x}%`,
            top: `${space.y}%`,
            '--presence-delay': `${index * 170}ms`,
          },
        };
      });
    },
    statusText() {
      if (this.phase === 'composing') return 'The room is gathering.';
      if (!this.totalLines) return 'Voices are finding their places.';
      return `Voices are finding their places. ${this.renderedLines} of ${this.totalLines}`;
    },
    playbackStatus() {
      if (!this.timeline) return 'The room is here.';
      if (this.elapsed < this.timeline.opening - 0.08) return 'The room is here. Listen.';
      if (this.elapsed > this.timeline.spokenEnd && this.elapsed < this.timeline.duration) return 'The room is still here.';
      return 'Listen.';
    },
    progress() {
      return this.timeline ? Math.min(1, this.elapsed / this.timeline.duration) : 0;
    },
    breathStyle() {
      const intensity = this.activeSpeakers.size ? 1 : 0.42;
      return { opacity: intensity };
    },
    errorMessage() {
      if (this.errorCode === 'rate_limited') return 'The room needs a moment before another gathering. Please try again shortly.';
      if (this.errorCode === 'voices_unavailable') return 'Usable voices could not gather this time. Please try the fragment again.';
      return 'The room could not form this time. Your fragment is still here, so you can try again.';
    },
    debugText() {
      const timeline = this.timeline ? {
        opening: this.timeline.opening,
        spokenEnd: this.timeline.spokenEnd,
        duration: this.timeline.duration,
        events: this.timeline.events.map((event) => ({
          id: event.id,
          speaker_id: event.speaker_id,
          start: Number(event.start.toFixed(3)),
          duration: Number(event.duration.toFixed(3)),
          timing: event.timing,
          anchor_id: event.anchor_id,
        })),
      } : null;
      return JSON.stringify({ scene: this.scene, timeline }, null, 2);
    },
  },
  mounted() {
    document.body.classList.add('room-route-active');
  },
  beforeUnmount() {
    document.body.classList.remove('room-route-active');
    this.cancelWork();
    this.engine?.stop();
    if (this.audioContext && this.audioContext.state !== 'closed') this.audioContext.close();
  },
  methods: {
    ensureAudio() {
      if (!this.audioContext || this.audioContext.state === 'closed') {
        const AudioContext = window.AudioContext || window.webkitAudioContext;
        this.audioContext = new AudioContext();
        this.engine = new RoomAudioEngine(this.audioContext);
      }
      this.audioContext.resume().catch(() => {});
    },
    cancelWork() {
      this.controller?.abort();
      this.controller = null;
      cancelAnimationFrame(this.animationFrame);
      this.animationFrame = 0;
    },
    async begin() {
      const value = this.fragment.replace(/\s+/g, ' ').trim();
      if (!value || ['composing', 'rendering'].includes(this.phase)) return;
      this.cancelWork();
      this.engine?.stop();
      this.ensureAudio();
      this.controller = new AbortController();
      this.errorCode = '';
      this.submittedFragment = value;
      this.scene = null;
      this.timeline = null;
      this.renderedLines = 0;
      this.totalLines = 0;
      this.activeSpeakers = new Set();
      this.phase = 'composing';
      try {
        const scene = await composeRoom(value, this.controller.signal);
        this.scene = scene;
        this.totalLines = scene.utterances.length;
        this.phase = 'rendering';
        const clips = await this.renderScene(scene, this.controller.signal);
        const renderedSpeakers = new Set(scene.utterances
          .filter((utterance) => clips.has(utterance.id))
          .map((utterance) => utterance.speaker_id));
        if (clips.size < 7 || renderedSpeakers.size < 5) throw new Error('speech_unavailable');
        this.timeline = resolveRoomTimeline(scene, clips);
        if (this.timeline.events.length < 7) throw new Error('speech_unavailable');
        this.phase = 'ready';
      } catch (error) {
        if (error?.name === 'AbortError') return;
        this.errorCode = error?.message || 'room_unavailable';
        this.phase = 'error';
      } finally {
        this.controller = null;
      }
    },
    async renderScene(scene, signal) {
      const clips = new Map();
      const groups = new Map(scene.speakers.map((speaker) => [speaker.id, []]));
      for (const utterance of scene.utterances) groups.get(utterance.speaker_id)?.push(utterance);
      const jobs = scene.speakers.map(async (speaker) => {
        let voiceId = speaker.voice.id;
        let successful = 0;
        for (const utterance of groups.get(speaker.id) || []) {
          try {
            const rendered = await synthesiseRoomLine({
              text: utterance.text,
              voiceId,
              language: scene.language,
              allowReplacement: successful === 0,
            }, signal);
            voiceId = rendered.voiceId;
            if (voiceId !== speaker.voice.id) speaker.voice = { id: voiceId, title: 'Replacement public voice', languages: [scene.language] };
            const buffer = await this.engine.decode(rendered.bytes);
            clips.set(utterance.id, { buffer, duration: buffer.duration });
            successful += 1;
            this.renderedLines += 1;
          } catch (error) {
            if (error?.name === 'AbortError') throw error;
            console.warn('room_line_unavailable', utterance.id, error?.message || error);
          }
        }
      });
      await Promise.all(jobs);
      return clips;
    },
    async listen() {
      if (!this.timeline || !this.scene) return;
      this.phase = 'playing';
      this.elapsed = 0;
      await this.engine.play(this.scene, this.timeline, () => {
        this.phase = 'ended';
        this.activeSpeakers = new Set();
        cancelAnimationFrame(this.animationFrame);
      });
      this.updatePlayback();
    },
    updatePlayback() {
      if (this.phase !== 'playing') return;
      this.elapsed = this.engine.elapsed();
      this.activeSpeakers = activeRoomSpeakers(this.timeline, this.elapsed);
      this.animationFrame = requestAnimationFrame(this.updatePlayback);
    },
    endEarly() {
      this.engine?.stop();
      cancelAnimationFrame(this.animationFrame);
      this.activeSpeakers = new Set();
      this.phase = 'ended';
    },
    reset() {
      this.cancelWork();
      this.engine?.stop();
      this.scene = null;
      this.timeline = null;
      this.submittedFragment = '';
      this.phase = 'idle';
      this.$nextTick(() => this.$refs.fragmentInput?.focus());
    },
  },
};
</script>

