<script>
import ProjectPageHeader from "./ui/ProjectPageHeader.vue";
import projectCaseStudyMixin from "../mixins/projectCaseStudyMixin";
import ProjectChapterNav from "./ui/ProjectChapterNav.vue";
import {
  fields,
  components,
  configurators,
  visibleFields,
  evaluate,
  defaultAnswers,
  fieldBySno,
  componentById,
} from "../data/playbookDemo";
import InsuranceRuleEngine from "./view/InsuranceRuleEngine.vue";

export default {
  name: "PlaybookTab",
  components: { ProjectChapterNav, ProjectPageHeader, InsuranceRuleEngine },
  mixins: [projectCaseStudyMixin],
  data() {
    return {
      fields,
      components,
      configurators,
      answers: defaultAnswers(),
    };
  },
  computed: {
    chapters() {
      return [
        { id: "case-chapter-0", label: "Requirements" },
        { id: "case-chapter-1", label: "Mapping" },
        { id: "case-chapter-2", label: "Try it" },
        { id: "case-chapter-3", label: "Automation" },
      ];
    },
    visible() {
      return visibleFields(this.answers);
    },
    hasSub() {
      return this.visible.some((f) => f.parent);
    },
    ev() {
      return evaluate(this.answers);
    },
  },
  methods: {
    fname(sno) {
      const f = fieldBySno(sno);
      return f ? f.name : sno;
    },
    iname(id) {
      const c = componentById(id);
      return c ? c.name : id;
    },
    matchCount(group) {
      return group.results.filter((r) => r.match).length;
    },
    winnerName(group) {
      return group.winning >= 0 ? group.cfg.scenarios[group.winning].name : "—";
    },
  },
};
</script>
